// generated by gen_matrix (full carrier composition matrix).
use vehje_bench_carrier as c;
use mockspace_bench_core::{timed, FfiBenchCall};
use mockspace_bench_macro::bench_variant;
#[allow(unused_imports)]
use std::sync::OnceLock;

#[bench_variant("carrier_opt_leaf_eqsat", sizes = [64, 256, 1024, 4096, 16384])]
fn run<const N: usize>(input: &[u8; N], output: &mut [u8; 8]) -> FfiBenchCall {
    static PREP: OnceLock<c::ir::Program> = OnceLock::new(); let prog = PREP.get_or_init(|| { let mut gp = c::GenParams::profile("leaf").unwrap(); gp.node_count = N; c::generate(&gp) }); let opt = c::optimize::optimize(prog, false, false, false, true); let bytes = c::ir::encode(&opt.prog, &c::ir::REC24); let d = c::ir::Decoded::parse(&bytes, c::ir::REC24).unwrap(); let mut r = vec![0u64; opt.prog.nodes.len().max(1)];
    const ITERS: usize = 16;
    timed! { run {
        let mut acc: u64 = 0;
        let mut k = 0usize;
        while k < ITERS {
            let seed = input[k % N] as u64 ^ (k as u64);
            c::interpret(&d, seed, &mut r); acc ^= c::access::checksum_at(&r, &opt.out_ids);
            k += 1;
        }
        output.copy_from_slice(&acc.to_le_bytes());
    } }
}
